items.code:
- callSync:
    try:
      call: http.post
      args:
        url: ${input.syncUrl}
        auth:
          type: OIDC
      result: syncResult
    except:
      [[1]]: e
      steps:
        - checkError:
            switch:
              - condition: ${not("HttpError" in e.tags)}
                next: failExecution
              - condition: ${e.[[2]] == 409}
                return: "skipped: a sync is already running"
        - failExecution:
            [[3]]: ${e}
